package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

var _ = decimal.NewFromInt // ensure import used if needed

type PartRec struct {
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

var WsEofFlag string // PIC X len=1 = "N"
var WsLabel string   // PIC X(20) len=20 = SPACES
var WsACount int64   // PIC 99 len=2 = 0
var WsTotalA int64   // PIC 999 len=3 = 0
var WsCount int64    // PIC 999 len=3 = 0

var partRec PartRec

var inputLines []string
var inputIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func delimitedBySpace(s string) string {
	if idx := strings.IndexByte(s, ' '); idx >= 0 {
		return s[:idx]
	}
	return s
}

func formatIntWidth(v int64, width int) string {
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	v = v % mod
	if v < 0 {
		v += mod
	}
	s := fmt.Sprintf("%d", v)
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	} else if len(s) > width {
		s = s[len(s)-width:]
	}
	return s
}

func MAIN_PARA() {
	OPEN_INPUT_PART_FILE()
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	CLOSE_PART_FILE()
	SUMMARY_PARA()
}

func OPEN_INPUT_PART_FILE() {
	WsEofFlag = "N"
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsTotalA = 0
	WsCount = 0

	data, err := os.ReadFile("input.dat")
	if err != nil {
		inputLines = []string{}
		inputIdx = 0
		return
	}
	content := string(data)
	content = strings.ReplaceAll(content, "\r\n", "\n")
	content = strings.ReplaceAll(content, "\r", "\n")
	if content == "" {
		inputLines = []string{}
		inputIdx = 0
		return
	}
	raw := strings.Split(content, "\n")
	// COBOL LINE SEQUENTIAL: if file ends with newline, last split is empty
	// That empty exists only if file ends with newline – it should not be a record.
	// strings.Split on "a\n" gives ["a",""]; we should drop final empty if source ended with newline.
	if len(raw) > 0 && raw[len(raw)-1] == "" && strings.HasSuffix(content, "\n") {
		raw = raw[:len(raw)-1]
	}
	inputLines = raw
	inputIdx = 0
}

func CLOSE_PART_FILE() {
}

func READ_PARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++

	// LINE SEQUENTIAL: pad with spaces if shorter than record length
	const recLen = 15
	if len(line) < recLen {
		line = line + strings.Repeat(" ", recLen-len(line))
	} else if len(line) > recLen {
		line = line[:recLen]
	}
	// parse
	partRec.LbPart = line[0:8]
	partRec.LbRegion = line[8:11]
	serialStr := line[11:15]
	// parse serial digits: digits only, spaces treated as 0? Actually spaces => empty => 0
	trimmed := strings.TrimSpace(serialStr)
	var v int64 = 0
	if trimmed != "" {
		// serial field should be numeric; parse digits, ignoring non-digit?
		// Use manual parse of digits substring (including leading zeros)
		var val int64 = 0
		for _, ch := range serialStr {
			if ch >= '0' && ch <= '9' {
				val = val*10 + int64(ch-'0')
			}
		}
		// But if serialStr contains spaces, the above would treat spaces as skip.
		// For padded case we want 0.
		// Distinguish: if serialStr is all spaces, val stays 0.
		v = val
		// Need to ensure 4-digit truncation semantics: if more than 4 digits? not.
		// For normal case serialStr is exactly 4 digits, val is correct.
		// However the above loop would collapse "00 1" etc. Not needed.
		_ = trimmed
	}
	// Alternative: try to parse trimmed as integer if it is all digits
	// Use val already; keep v
	// To handle correctly overflow/store low-order digits, mimic COBOL: keep low 4 digits
	// But input is at most 4 digits, so fine.
	partRec.LbSerial = v % 10000
	if partRec.LbSerial < 0 {
		partRec.LbSerial += 10000
	}
	WsEofFlag = "N"
}

func PROCESS_PARA() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0

	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	WsACount += int64(strings.Count(partRec.LbPart, "A"))

	// STRING ...
	regionPart := delimitedBySpace(partRec.LbRegion)
	partPart := delimitedBySpace(partRec.LbPart)
	serialPart := formatIntWidth(partRec.LbSerial, 4)

	concat := regionPart + "-" + partPart + "-" + serialPart
	if len(concat) > 20 {
		concat = concat[:20]
	}
	// INTO WS-LABEL (blank first)
	if len(concat) < 20 {
		WsLabel = concat + strings.Repeat(" ", 20-len(concat))
	} else {
		WsLabel = concat
	}
	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	WsTotalA += WsACount
	WsCount += 1

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL is X(20), WS-A-COUNT is 99 zero-padded width 2
	line := WsLabel + " A=" + formatIntWidth(WsACount, 2)
	fmt.Println(line)

	READ_PARA()
}

func SUMMARY_PARA() {
	line := "LABELS: " + formatIntWidth(WsCount, 3) + " A-TOTAL: " + formatIntWidth(WsTotalA, 3)
	fmt.Println(line)
}

func main() {
	MAIN_PARA()
}
